function Wait-Resources([string]$Phase){while($true){$free=(Get-CimInstance Win32_OperatingSystem).FreePhysicalMemory/1MB;$gpu=[int](([string]((& nvidia-smi --query-gpu=memory.free --format=csv,noheader,nounits)|Select-Object -First 1)).Trim());if($free-ge40-and$gpu-ge16000){return};Start-Sleep 30}}
function Run-Python([string]$Phase,[string]$Args,[string]$LogName){Wait-Resources $Phase;$log=Join-Path $runtime $LogName;if(Test-Path $log){throw "$Phase log already exists"};& cmd.exe /d /c ('"'+$python+'" -u '+$Args+' >> "'+$log+'" 2>&1');if($LASTEXITCODE-ne0){throw "$Phase exited $LASTEXITCODE"}}
try{
 if(Test-Path $mainLog){throw 'pipeline log already exists'}
 $expected=@{$subjectEntry='463861faddff7b0c72e473eacbc7f3d8fb47c19b720e1d0f734e725207bf167d';$randomEntry='d7d055dd5a03c17f07d5ae58ff436ff44af74a837e1e9e2f68162b2c481ef986';$completeEntry='546e30a39bbce20b31d0f62179b277d43cb6a2983a2abdb0486dd7838950b49b';$compactEntry='c272f4caa80c68ce9b3e5dc44b5f50451aa417d26fbe9a7d35e2e66cea224616'};foreach($entry in $expected.Keys){if((Get-FileHash $entry -Algorithm SHA256).Hash.ToLowerInvariant()-ne$expected[$entry]){throw "source SHA mismatch: $entry"}}
 if((Get-FileHash (Join-Path $experiment 'protocol\MECHANISM_CLOSURE_ANALYSIS_LOCK.md') -Algorithm SHA256).Hash.ToLowerInvariant()-ne'ac12d33f7d30b2c846ec4c4fb07f8513bf25e372943a767b134883bf095a7c88'){throw 'analysis lock SHA mismatch'}
 if((Get-FileHash (Join-Path $experiment 'protocol\FINAL_PROJECTOR_AMENDMENT.md') -Algorithm SHA256).Hash.ToLowerInvariant()-ne'aec1e604d38f1901bd9eca7e072e30a3d496a28061a726ebbe63133259b0e474'){throw 'amendment SHA mismatch'}
 "SUBJECT_COMPACT_F4_START utc=$([datetime]::UtcNow.ToString('o'))"|Out-File $mainLog -Encoding utf8
 $endpointPath=Join-Path $cell 'REPLICA_ENDPOINT_AUDIT_V1.json';while(-not(Test-Path $endpointPath)){Start-Sleep 15};$endpoint=Get-Content $endpointPath -Raw|ConvertFrom-Json;$epochs=@($endpoint.schedule|ForEach-Object{[int]$_.epoch}|Sort-Object -Unique);if($epochs.Count-ne6){throw 'invalid endpoint schedule'}
 while($true){$valid=0;foreach($epoch in $epochs){$p=Join-Path $cell ("checkpoint_mechanism_v1\epoch_{0:d3}.json"-f$epoch);if(Test-Path $p){$j=Get-Content $p -Raw|ConvertFrom-Json;if($j.status-eq'CHECKPOINT_MECHANISM_COMPLETE_REPLICA_ONLY'-and$j.final_heldout_accessed-eq$false){$valid++}}};if($valid-eq6){break};Start-Sleep 20}
 $subjectV1=Join-Path $cell 'SUBJECT_SESSION_AUDIT_V1.json';if(-not(Test-Path $subjectV1)){Run-Python 'SUBJECT_V1' ('"'+$subjectEntry+'" --task OpenBMI_MI --fold 4') 'scheduled_subject_session_EEGNet_OpenBMI_MI_f4_v2.log'};$sv1=Get-Content $subjectV1 -Raw|ConvertFrom-Json;if($sv1.status-ne'SUBJECT_SESSION_AUDIT_COMPLETE_POST_OUTCOME_DESCRIPTIVE'-or$sv1.final_heldout_accessed-ne$false-or@($sv1.subject_session_signature_rows).Count-ne68){throw 'subject V1 invalid'};$baseSha=(Get-FileHash $subjectV1 -Algorithm SHA256).Hash.ToLowerInvariant()
 foreach($draw in 0..19){$tag='{0:d2}'-f$draw;$out=Join-Path $cell "train_random_subject_v1\draw_$tag.json";if(-not(Test-Path $out)){Run-Python "TRAIN_RANDOM_D$tag" ('"'+$randomEntry+'" --task OpenBMI_MI --fold 4 --draw '+$draw) "scheduled_train_random_subject_EEGNet_OpenBMI_MI_f4_d${tag}_v2.log"};$j=Get-Content $out -Raw|ConvertFrom-Json;if($j.status-ne'TRAIN_RANDOM_SUBJECT_DRAW_COMPLETE'-or[int]$j.draw-ne$draw-or$j.final_heldout_accessed-ne$false-or@($j.train_subject_session_rows).Count-ne52){throw "random draw $draw invalid"}}
 $subjectV2=Join-Path $cell 'SUBJECT_SESSION_AUDIT_V2.json';if(-not(Test-Path $subjectV2)){Run-Python 'SUBJECT_V2' ('"'+$completeEntry+'" --task OpenBMI_MI --fold 4 --base-sha '+$baseSha) 'scheduled_subject_session_complete_EEGNet_OpenBMI_MI_f4_v3.log'};$sv2=Get-Content $subjectV2 -Raw|ConvertFrom-Json;if($sv2.status-ne'SUBJECT_SESSION_AUDIT_COMPLETE_POST_OUTCOME_DESCRIPTIVE'-or$sv2.final_heldout_accessed-ne$false-or@($sv2.subject_session_signature_rows).Count-ne68){throw 'subject V2 invalid'};$sha=(Get-FileHash $subjectV2 -Algorithm SHA256).Hash.ToLowerInvariant()
 $compact=Join-Path $runtime 'compact_preview\eegnet_openbmi_mi_fold4_seed0_v3\PROVENANCE.json';if(-not(Test-Path $compact)){Run-Python 'COMPACT' ('"'+$compactEntry+'" --task OpenBMI_MI --fold 4 --subject-v2-sha '+$sha) 'scheduled_compact_EEGNet_OpenBMI_MI_f4_v3.log'};$cp=Get-Content $compact -Raw|ConvertFrom-Json;if($cp.status-ne'CELL_COMPACT_PREVIEW_COMPLETE_NOT_20_CELL_RESULT'-or$cp.final_heldout_accessed-ne$false){throw 'compact output invalid'}
 "SUBJECT_COMPACT_F4_COMPLETE sha=$sha utc=$([datetime]::UtcNow.ToString('o'))"|Out-File $mainLog -Append -Encoding utf8;exit 0
}catch{if(Test-Path $mainLog){"SUBJECT_COMPACT_F4_EXCEPTION $_ utc=$([datetime]::UtcNow.ToString('o'))"|Out-File $mainLog -Append -Encoding utf8};exit 1}
